package com.yigongbao.backup.admin;
import cn.dev33.satoken.stp.StpUtil; import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.fasterxml.jackson.databind.ObjectMapper; import com.yigongbao.backup.cold.*; import com.yigongbao.backup.common.ApiResponse; import com.yigongbao.backup.job.*; import com.yigongbao.backup.order.ColdSupplementCoverageService; import com.yigongbao.backup.storage.volume.StorageVolumeEntity; import com.yigongbao.backup.storage.volume.StorageVolumeMapper; import com.yigongbao.backup.storage.volume.StorageVolumeStatus; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.List; import java.util.UUID;
/** 管理员冷备磁盘、批次和状态流转接口。 */
@RestController @RequestMapping("/api/v1/admin/cold-batches") @RequiredArgsConstructor
public class AdminColdBatchController {private final ColdDiskMapper disks;private final ColdBatchMapper batches;private final ColdBatchWorkflowService workflow;private final ColdSupplementCoverageService supplementCoverage;private final StorageVolumeMapper volumes;private final PersistentJobCoordinator jobs;private final ObjectMapper mapper;private static String rid(){return UUID.randomUUID().toString();}private void admin(){StpUtil.checkRole("ADMIN");}
 @GetMapping("/disks") public ApiResponse<java.util.List<ColdDiskEntity>> disks(){admin();return ApiResponse.ok(disks.selectList(Wrappers.<ColdDiskEntity>lambdaQuery().eq(ColdDiskEntity::getStatus,"REGISTERED")),rid());}
 @PostMapping("/disks") public ApiResponse<ColdDiskEntity> registerDisk(@RequestBody RegisterDisk c){admin();if(c==null||c.diskCode()==null||c.diskCode().isBlank()||c.label()==null||c.label().isBlank())throw new IllegalArgumentException("冷备盘标识和标签不能为空");ColdDiskEntity d=new ColdDiskEntity();d.setDiskCode(c.diskCode());d.setVolumeSerial(c.volumeSerial());d.setMarkerUuid(c.markerUuid());d.setFileSystem(c.fileSystem());d.setLabel(c.label());d.setPhysicalLocation(c.physicalLocation());d.setStatus("REGISTERED");d.setCapacityBytes(c.capacityBytes());d.setFreeBytes(c.freeBytes());disks.insert(d);return ApiResponse.ok(d,rid());}
 @GetMapping public ApiResponse<java.util.List<ColdBatchEntity>> list(){admin();return ApiResponse.ok(batches.selectList(Wrappers.<ColdBatchEntity>lambdaQuery().orderByDesc(ColdBatchEntity::getCreateTime)),rid());}
 @PostMapping public ApiResponse<ColdBatchEntity> create(@RequestBody Create c){admin();ColdDiskEntity d=disks.selectById(c.diskId());if(d==null||!"REGISTERED".equals(d.getStatus()))throw new IllegalArgumentException("目标冷备盘不可用");ColdBatchEntity b=new ColdBatchEntity();b.setBatchNo("CB-"+UUID.randomUUID());b.setDiskId(c.diskId());b.setOrderTimeFrom(c.from());b.setOrderTimeTo(c.to());b.setFormat("ZIP64_V1");b.setStatus("CREATED");b.setOrderCount(0);b.setArtifactCount(0);b.setTotalSize(0L);b.setHotCleanupStatus("PENDING");batches.insert(b);return ApiResponse.ok(b,rid());}
 @PostMapping("/{id}/start") public ApiResponse<ColdBatchEntity> start(@PathVariable("id") long id){admin();return ApiResponse.ok(workflow.start(id),rid());}
 /** 将指定订单包写入管理员选择的冷备盘；系统不会自动探测或操作其他盘。 */
 @PostMapping("/{id}/write") public ApiResponse<JobTask> write(@PathVariable("id") long id,@RequestBody Write c) throws Exception {admin();if(c==null||c.targetStorageVolumeId()==null||c.orderPackages()==null||c.orderPackages().isEmpty())throw new IllegalArgumentException("冷备目标卷和订单包不能为空");if(batches.selectById(id)==null)throw new IllegalArgumentException("批次不存在");StorageVolumeEntity volume=volumes.selectById(c.targetStorageVolumeId());if(volume==null||!StorageVolumeStatus.Tier.COLD.name().equals(volume.getTier())||!StorageVolumeStatus.Mount.ONLINE.name().equals(volume.getMountStatus())||!(StorageVolumeStatus.Write.ACTIVE.name().equals(volume.getWriteStatus())||StorageVolumeStatus.Write.STANDBY.name().equals(volume.getWriteStatus())))throw new IllegalArgumentException("目标冷备卷不可写入");return job("COLD_WRITE",new ColdWriteJobHandler.Payload(id,c.targetStorageVolumeId(),c.orderPackages().stream().distinct().sorted().toList(),c.sha256()),c.targetStorageVolumeId());}
 @PostMapping("/{id}/complete") public ApiResponse<ColdBatchEntity> complete(@PathVariable("id") long id,@RequestBody Complete c){admin();ColdBatchEntity completed=workflow.complete(id,c.orders(),c.artifacts(),c.bytes(),c.sha256());supplementCoverage.markCovered(id,c.orderCodes(),StpUtil.getLoginIdAsLong());return ApiResponse.ok(completed,rid());}
 @PostMapping("/{id}/verify") public ApiResponse<ColdBatchEntity> verify(@PathVariable("id") long id){admin();return ApiResponse.ok(workflow.verify(id),rid());}
 /** 冷备验证后由管理员显式提交整批热备包路径；删除成功后才落库为 CLEANED。 */
 @PostMapping({"/{id}/hot-cleanup", "/{id}/hot-cleanup-confirm"}) public ApiResponse<JobTask> cleanup(@PathVariable("id") long id,@RequestBody Cleanup c) throws Exception {admin();if(c==null||c.packageKeys()==null||c.packageKeys().isEmpty())throw new IllegalArgumentException("必须提交整批热备订单包路径");ColdBatchEntity b=batches.selectById(id);if(b==null||!"VERIFIED".equals(b.getStatus()))throw new IllegalStateException("批次未通过验证");return job("HOT_CLEANUP",new HotCleanupJobHandler.Payload(id,c.packageKeys().stream().distinct().sorted().toList()));}
 private ApiResponse<JobTask> job(String type,Object payload)throws Exception{return job(type,payload,null);}
 private ApiResponse<JobTask> job(String type,Object payload,Long targetStorageVolumeId)throws Exception{long actor=StpUtil.getLoginIdAsLong();String json=mapper.writeValueAsString(payload);JobEntity j=jobs.create(type,JobIdempotency.key(type,actor,json),actor,json,targetStorageVolumeId);return ApiResponse.ok(new JobTask(j.getId(),j.getJobNo(),j.getStatus()),rid());}
 public record Create(Long diskId,LocalDateTime from,LocalDateTime to){}
 public record RegisterDisk(String diskCode,String volumeSerial,String markerUuid,String fileSystem,String label,String physicalLocation,Long capacityBytes,Long freeBytes){}
 public record Write(Long targetStorageVolumeId,List<String> orderPackages,String sha256){}
 public record Complete(int orders,int artifacts,long bytes,String sha256,List<String> orderCodes){}
 public record Cleanup(List<String> packageKeys){}
 public record JobTask(Long jobId,String jobNo,String status){}
 private static List<String> orderCodes(List<String> packages){return packages.stream().map(AdminColdBatchController::orderCode).filter(java.util.Objects::nonNull).distinct().toList();}
 private static String orderCode(String key){if(key==null)return null;String normalized=key.replace('\\','/');String[] parts=normalized.split("/");return parts.length>=3&&"orders".equals(parts[0])?parts[1]:null;}
}
